import net.minecraft.client.Minecraft;
import net.minecraft.client.gui.FontRenderer;
import net.minecraft.client.gui.ScaledResolution;

import org.lwjgl.opengl.GL11;

import java.awt.image.BufferedImage;
import java.io.BufferedReader;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import java.nio.charset.StandardCharsets;

import javax.imageio.ImageIO;

/**
 * Packed Noto Sans SC Regular atlas renderer used by the whole OpenMaver UI.
 *
 * <p>The atlas is generated by {@code tools/GenerateHudFontAtlas.py} at one resolution per
 * Minecraft GUI scale (1x..8x). Latin and Chinese glyphs come from Noto Sans SC Regular.
 * Characters that are not present in the atlas fall back to Minecraft's font.
 *
 * <p>The atlas matching the current GUI scale is used so each glyph texel covers exactly one
 * framebuffer pixel. Sampling the old 1x atlas at GUI scale 2/3 magnified the text and was what
 * made it look blurry.
 *
 * <p>Minecraft formatting codes ({@code §l}, {@code §r}, ...) are consumed by the renderer
 * instead of being drawn; {@code §l} is emulated by drawing each glyph twice.
 */
public final class HudFont {

    private static final char FORMATTING = '\u00a7';

    /** Small upward nudge so the packed glyphs line up with Minecraft's baseline. */
    private static final int TEXT_LIFT = 2;

    /** Highest packed atlas generated by tools/GenerateHudFontAtlas.py. */
    private static final int MAX_ATLAS_SCALE = 8;

    /**
     * Load an atlas with more texels than the bare GUI scale. Normal text is then
     * supersampled (sharp), and large titles/buttons are upscaled far less than before,
     * which removes most of the blur at fractional font sizes.
     */
    private static final int ATLAS_DETAIL = 3;

    private static final long GUI_SCALE_REFRESH_MS = 500L;
    private static final boolean[] SCALE_FAILED = new boolean[MAX_ATLAS_SCALE + 1];
    private static final FontState HUD_STATE = new FontState();
    private static final FontState MENU_STATE = new FontState();

    private static int textureId;
    private static int cell;
    private static int columns;
    private static int padding;
    private static int atlasWidth;
    private static int atlasHeight;
    private static int fontTop;
    private static int fontHeight;
    private static int baseline;
    private static int atlasScale = 1;
    /** Baseline-to-ink-top distance of the 1x atlas, in GUI units. */
    private static int canonicalAscent;
    private static int[] codes;
    private static int[] widths;
    private static boolean initialized;
    private static boolean failed;
    private static boolean menuFont;

    private static int guiScale;
    private static long nextScaleRefresh;

    private HudFont() {
    }

    private static final class FontState {
        final boolean[] scaleFailed = new boolean[MAX_ATLAS_SCALE + 1];
        int textureId;
        int cell;
        int columns;
        int padding;
        int atlasWidth;
        int atlasHeight;
        int fontTop;
        int fontHeight;
        int baseline;
        int atlasScale = 1;
        int canonicalAscent;
        int[] codes;
        int[] widths;
        boolean initialized;
        boolean failed;
    }

    public static void useMenuFont() {
        selectFont(true);
    }

    public static void useHudFont() {
        selectFont(false);
    }

    private static void selectFont(boolean menu) {
        if (menuFont == menu) {
            return;
        }
        saveFontState(menuFont ? MENU_STATE : HUD_STATE);
        menuFont = menu;
        restoreFontState(menu ? MENU_STATE : HUD_STATE);
    }

    private static void saveFontState(FontState state) {
        state.textureId = textureId;
        state.cell = cell;
        state.columns = columns;
        state.padding = padding;
        state.atlasWidth = atlasWidth;
        state.atlasHeight = atlasHeight;
        state.fontTop = fontTop;
        state.fontHeight = fontHeight;
        state.baseline = baseline;
        state.atlasScale = atlasScale;
        state.canonicalAscent = canonicalAscent;
        state.codes = codes;
        state.widths = widths;
        state.initialized = initialized;
        state.failed = failed;
        System.arraycopy(SCALE_FAILED, 0, state.scaleFailed, 0, SCALE_FAILED.length);
    }

    private static void restoreFontState(FontState state) {
        textureId = state.textureId;
        cell = state.cell;
        columns = state.columns;
        padding = state.padding;
        atlasWidth = state.atlasWidth;
        atlasHeight = state.atlasHeight;
        fontTop = state.fontTop;
        fontHeight = state.fontHeight;
        baseline = state.baseline;
        atlasScale = state.atlasScale;
        canonicalAscent = state.canonicalAscent;
        codes = state.codes;
        widths = state.widths;
        initialized = state.initialized;
        failed = state.failed;
        System.arraycopy(state.scaleFailed, 0, SCALE_FAILED, 0, SCALE_FAILED.length);
    }

    public static int getStringWidth(FontRenderer fallback, String text) {
        return getStringWidth(fallback, text, 1.0F);
    }

    public static int getStringWidth(FontRenderer fallback, String text, float size) {
        if (text == null || text.length() == 0) {
            return 0;
        }
        if (!ensureInitialized()) {
            return Math.round(fallback.getStringWidth(text) * size);
        }
        float width = 0.0F;
        boolean bold = false;
        for (int i = 0; i < text.length(); i++) {
            char c = text.charAt(i);
            if (c == FORMATTING && i + 1 < text.length()) {
                char code = text.charAt(++i);
                if (code == 'l' || code == 'L') {
                    bold = true;
                } else if (code == 'r' || code == 'R') {
                    bold = false;
                }
                continue;
            }
            int index = indexOf(c);
            if (index >= 0) {
                float advance = Math.max(1.0F, widths[index] * size - 0.25F * size);
                if (bold) {
                    advance += boldOffset();
                }
                width += advance;
            } else {
                width += fallback.getStringWidth(String.valueOf(c)) * size;
            }
        }
        return Math.max(0, Math.round(width));
    }

    public static void drawString(FontRenderer fallback, String text, int x, int y, int color) {
        drawString(fallback, text, x, y, color, 1.0F);
    }

    public static void drawString(FontRenderer fallback, String text, int x, int y, int color,
            float size) {
        if (text == null || text.length() == 0) {
            return;
        }
        if (!ensureInitialized()) {
            fallback.drawStringWithShadow(text, x, y, color);
            return;
        }
        if ((color >>> 24) != 0) {
            drawRun(fallback, text, x, y, color, false, size);
        }
    }

    public static void drawCenteredString(FontRenderer fallback, String text, int centerX, int y,
            int color) {
        drawString(fallback, text, centerX - getStringWidth(fallback, text) / 2, y, color);
    }

    public static void drawStringWithShadow(FontRenderer fallback, String text, int x, int y,
            int color, float size) {
        if (text == null || text.length() == 0) {
            return;
        }
        if (!ensureInitialized()) {
            fallback.drawStringWithShadow(text, x, y, color);
            return;
        }
        if ((color >>> 24) != 0) {
            drawRun(fallback, text, x, y + 1, color, true, size);
            drawRun(fallback, text, x, y, color, false, size);
        }
    }

    public static void drawStringWithShadow(FontRenderer fallback, String text, int x, int y,
            int color) {
        if (text == null || text.length() == 0) {
            return;
        }
        if (!ensureInitialized()) {
            fallback.drawStringWithShadow(text, x, y, color);
            return;
        }
        if ((color >>> 24) != 0) {
            drawRun(fallback, text, x, y + 1, color, true, 1.0F);
            drawRun(fallback, text, x, y, color, false, 1.0F);
        }
    }

    private static int drawRun(FontRenderer fallback, String text, int x, int y, int color,
            boolean shadow, float size) {
        float cursor = x;
        // Keep the 1x baseline, whichever atlas resolution is active. For a matched GUI scale
        // this also lands the quad on an exact framebuffer pixel, so no resampling blur occurs.
        float drawY = y - TEXT_LIFT * size + canonicalAscent * size
                - (baseline - fontTop) / (float) atlasScale * size;
        float glyphHeight = fontHeight / (float) atlasScale * size;
        // Snap the glyph band to whole framebuffer pixels. Fractional vertical
        // positions were another source of soft/blurry text at odd GUI scales.
        int framebufferScale = Math.max(1, guiScale);
        drawY = Math.round(drawY * framebufferScale) / (float) framebufferScale;
        glyphHeight = Math.max(1.0F, Math.round(glyphHeight * framebufferScale))
                / (float) framebufferScale;
        // Start from a known color so the first glColor4f cannot be skipped by a stale cache.
        GlColor.restore();
        GL11.glPushAttrib(GL11.GL_ENABLE_BIT | GL11.GL_TEXTURE_BIT | GL11.GL_COLOR_BUFFER_BIT);
        GL11.glDisableClientState(GL11.GL_VERTEX_ARRAY);
        GL11.glDisableClientState(GL11.GL_COLOR_ARRAY);
        GL11.glDisableClientState(GL11.GL_TEXTURE_COORD_ARRAY);
        GL11.glDisable(GL11.GL_CULL_FACE);
        GL11.glDisable(GL11.GL_ALPHA_TEST);
        // Keep the caller's scissor active so text follows animated panels and scroll clips.
        GL11.glDisable(GL11.GL_POLYGON_SMOOTH);
        GL11.glDisable(GL11.GL_LINE_SMOOTH);
        GL11.glDisable(GL11.GL_COLOR_LOGIC_OP);
        GL11.glShadeModel(GL11.GL_SMOOTH);
        GL11.glEnable(GL11.GL_TEXTURE_2D);
        // Some world renderers leave a REPLACE/COMBINE texture env behind. With an
        // alpha-only font atlas that can turn every glyph black; force MODULATE.
        GL11.glTexEnvi(GL11.GL_TEXTURE_ENV, GL11.GL_TEXTURE_ENV_MODE, GL11.GL_MODULATE);
        GL11.glEnable(GL11.GL_BLEND);
        GL11.glBlendFunc(GL11.GL_SRC_ALPHA, GL11.GL_ONE_MINUS_SRC_ALPHA);
        GL11.glDisable(GL11.GL_DEPTH_TEST);
        GL11.glDisable(GL11.GL_LIGHTING);
        GL11.glBindTexture(GL11.GL_TEXTURE_2D, textureId);
        int alpha = color >>> 24;
        float red = (color >> 16 & 0xFF) / 255.0f;
        float green = (color >> 8 & 0xFF) / 255.0f;
        float blue = (color & 0xFF) / 255.0f;
        GlColor.set(red, green, blue, alpha / 255.0f * (shadow ? 0.35f : 1.0f));
        GL11.glBegin(GL11.GL_QUADS);
        boolean bold = false;
        for (int i = 0; i < text.length(); i++) {
            char c = text.charAt(i);
            if (c == FORMATTING && i + 1 < text.length()) {
                char code = text.charAt(++i);
                if (code == 'l' || code == 'L') {
                    bold = true;
                } else if (code == 'r' || code == 'R') {
                    bold = false;
                }
                continue;
            }
            int index = indexOf(c);
            if (index < 0) {
                GL11.glEnd();
                if (!shadow) {
                    GlColor.restore();
                    fallback.drawStringWithShadow(String.valueOf(c), cursor, y, color);
                }
                cursor += fallback.getStringWidth(String.valueOf(c)) * size;
                GL11.glEnable(GL11.GL_TEXTURE_2D);
                GL11.glEnable(GL11.GL_BLEND);
                GL11.glBlendFunc(GL11.GL_SRC_ALPHA, GL11.GL_ONE_MINUS_SRC_ALPHA);
                GL11.glDisable(GL11.GL_DEPTH_TEST);
                GL11.glDisable(GL11.GL_LIGHTING);
                GL11.glBindTexture(GL11.GL_TEXTURE_2D, textureId);
                GlColor.set(red, green, blue, alpha / 255.0f * (shadow ? 0.35f : 1.0f));
                GL11.glBegin(GL11.GL_QUADS);
                continue;
            }
            int cellX = index % columns * cell;
            int cellY = index / columns * cell;
            float sourceWidth = widths[index] + padding * 2;
            float width = sourceWidth * size;
            // The cell is stored at atlasScale texels per GUI unit; map the same region to the
            // same on-screen size at every scale.
            float u0 = cellX / (float) atlasWidth;
            float v0 = (cellY + fontTop) / (float) atlasHeight;
            float u1 = (cellX + sourceWidth * atlasScale) / (float) atlasWidth;
            float v1 = (cellY + fontTop + fontHeight) / (float) atlasHeight;
            drawGlyph(cursor - padding * size, drawY, width, glyphHeight, u0, v0, u1, v1);
            if (bold) {
                // Fake bold must be a ~1 framebuffer-pixel thickening. Offsetting by the
                // full font size (as before) made large titles look like two blurred copies.
                float boldOffset = boldOffset();
                drawGlyph(cursor - padding * size + boldOffset, drawY, width, glyphHeight,
                        u0, v0, u1, v1);
                cursor += boldOffset;
            }
            cursor += Math.max(1.0F, widths[index] * size - 0.25F * size);
        }
        GL11.glEnd();
        GL11.glPopAttrib();
        GlColor.restore();
        return Math.round(cursor);
    }

    /** Bold thickening in GUI units, kept at about one framebuffer pixel. */
    private static float boldOffset() {
        return 1.0F / Math.max(1, Math.min(MAX_ATLAS_SCALE, currentGuiScale()));
    }

    private static void drawGlyph(float x, float y, float width, float height,
            float u0, float v0, float u1, float v1) {
        float right = x + width;
        float bottom = y + height;
        GL11.glTexCoord2f(u0, v0);
        GL11.glVertex2f(x, y);
        GL11.glTexCoord2f(u1, v0);
        GL11.glVertex2f(right, y);
        GL11.glTexCoord2f(u1, v1);
        GL11.glVertex2f(right, bottom);
        GL11.glTexCoord2f(u0, v1);
        GL11.glVertex2f(x, bottom);
    }

    private static boolean ensureInitialized() {
        return ensureInitialized(Math.min(MAX_ATLAS_SCALE,
                currentGuiScale() * ATLAS_DETAIL));
    }

    private static boolean ensureInitialized(int wantedScale) {
        int target = Math.max(1, Math.min(wantedScale, MAX_ATLAS_SCALE));
        if (initialized && atlasScale == target) {
            return true;
        }
        if (failed) {
            return false;
        }
        // Never retry resolutions known to be missing, and keep the best loaded atlas when the
        // requested one is unavailable.
        if (initialized && atlasScale < target) {
            boolean blocked = true;
            for (int scale = atlasScale + 1; scale <= target; scale++) {
                if (!SCALE_FAILED[scale]) {
                    blocked = false;
                    break;
                }
            }
            if (blocked) {
                return true;
            }
        }
        for (int scale = target; scale >= 1; scale--) {
            if (SCALE_FAILED[scale]) {
                continue;
            }
            try {
                loadAtlas(scale);
                initialized = true;
                return true;
            } catch (Throwable t) {
                SCALE_FAILED[scale] = true;
                if (scale == 1) {
                    failed = true;
                    System.err.println("[OpenMaver] UI font atlas unavailable; using "
                            + "Minecraft font: " + t);
                }
            }
        }
        failed = true;
        return false;
    }

    /**
     * Current Minecraft GUI scale (clamped to 1..8). Cached briefly because the font renderer
     * draws dozens of strings per frame and building a {@link ScaledResolution} each time would be
     * wasteful.
     */
    private static int currentGuiScale() {
        long now = System.currentTimeMillis();
        if (now < nextScaleRefresh && guiScale > 0) {
            return guiScale;
        }
        nextScaleRefresh = now + GUI_SCALE_REFRESH_MS;
        try {
            Minecraft minecraft = Minecraft.getMinecraft();
            if (minecraft != null) {
                guiScale = new ScaledResolution(minecraft).getScaleFactor();
            }
        } catch (Throwable ignored) {
            // Fall back to the previous value (or 1 below).
        }
        if (guiScale < 1) {
            guiScale = 1;
        } else if (guiScale > MAX_ATLAS_SCALE) {
            guiScale = MAX_ATLAS_SCALE;
        }
        return guiScale;
    }

    private static String fontResource(String name, int scale, String extension) {
        String suffix = scale == 1 ? "" : "@" + scale + "x";
        String resourceName = name.replace("HudFont", menuFont ? "MenuFont" : "HudFont");
        return "/assets/openmaver/font/" + resourceName + suffix + extension;
    }

    /** Loads one atlas resolution. Static fields are only updated after a full successful load. */
    private static void loadAtlas(int scale) throws Exception {
        int loadedCell;
        int loadedColumns;
        int loadedPadding;
        int loadedFontTop;
        int loadedFontHeight;
        int loadedBaseline;
        int loadedScale;
        int loadedAscent;
        int[] loadedCodes;
        int[] loadedWidths;
        int count;

        try (InputStream stream = HudFont.class.getResourceAsStream(
                fontResource("HudFontMetrics", scale, ".txt"))) {
            if (stream == null) {
                throw new IllegalStateException("UI font metrics resource is missing");
            }
            BufferedReader reader = new BufferedReader(new InputStreamReader(stream,
                    StandardCharsets.US_ASCII));
            String header = reader.readLine();
            String glyphLine = reader.readLine();
            if (header == null || glyphLine == null) {
                throw new IllegalStateException("UI font metrics are incomplete");
            }
            // Header: cell,columns,padding,inkTop,inkHeight,baseline,scale,ascent1
            // (atlas pixels, except padding and ascent1 which are GUI units).
            String[] head = header.split(",");
            if (head.length != 8) {
                throw new IllegalStateException("UI font metrics header is invalid");
            }
            loadedCell = Integer.parseInt(head[0]);
            loadedColumns = Integer.parseInt(head[1]);
            loadedPadding = Integer.parseInt(head[2]);
            loadedFontTop = Integer.parseInt(head[3]);
            loadedFontHeight = Integer.parseInt(head[4]);
            loadedBaseline = Integer.parseInt(head[5]);
            loadedScale = Integer.parseInt(head[6]);
            loadedAscent = Integer.parseInt(head[7]);
            if (loadedScale != scale) {
                throw new IllegalStateException("UI font metrics scale mismatch");
            }
            String[] values = glyphLine.split(",");
            if (values.length < 2 || (values.length & 1) != 0) {
                throw new IllegalStateException("UI font metrics have an invalid glyph count");
            }
            count = values.length / 2;
            loadedCodes = new int[count];
            loadedWidths = new int[count];
            for (int i = 0; i < count; i++) {
                loadedCodes[i] = Integer.parseInt(values[i * 2]);
                loadedWidths[i] = Integer.parseInt(values[i * 2 + 1]);
            }
        }
        if (loadedCell <= 0 || loadedColumns <= 0 || loadedPadding < 0
                || loadedFontHeight <= 0 || loadedFontTop < 0
                || loadedFontTop + loadedFontHeight > loadedCell
                || loadedBaseline < loadedFontTop || loadedAscent <= 0) {
            throw new IllegalStateException("UI font metrics dimensions are invalid");
        }

        BufferedImage image;
        try (InputStream stream = HudFont.class.getResourceAsStream(
                fontResource("HudFontAtlas", scale, ".png"))) {
            if (stream == null) {
                throw new IllegalStateException("UI font atlas resource is missing");
            }
            image = ImageIO.read(stream);
        }
        int loadedAtlasWidth = loadedColumns * loadedCell;
        if (image == null || image.getWidth() != loadedAtlasWidth
                || image.getHeight() % loadedCell != 0) {
            throw new IllegalStateException("UI font atlas has invalid dimensions");
        }
        int loadedAtlasHeight = image.getHeight();
        if (count > (loadedAtlasHeight / loadedCell) * loadedColumns) {
            throw new IllegalStateException("UI font atlas is too small for its metrics");
        }

        ByteBuffer buffer = ByteBuffer.allocateDirect(loadedAtlasWidth * loadedAtlasHeight)
                .order(ByteOrder.nativeOrder());
        for (int row = 0; row < loadedAtlasHeight; row++) {
            for (int column = 0; column < loadedAtlasWidth; column++) {
                buffer.put((byte) image.getRaster().getSample(column, row, 0));
            }
        }
        buffer.flip();
        GL11.glPushAttrib(GL11.GL_TEXTURE_BIT);
        if (textureId == 0) {
            textureId = GL11.glGenTextures();
        }
        GL11.glBindTexture(GL11.GL_TEXTURE_2D, textureId);
        GL11.glTexParameteri(GL11.GL_TEXTURE_2D, GL11.GL_TEXTURE_MIN_FILTER, GL11.GL_LINEAR);
        GL11.glTexParameteri(GL11.GL_TEXTURE_2D, GL11.GL_TEXTURE_MAG_FILTER, GL11.GL_LINEAR);
        GL11.glTexParameteri(GL11.GL_TEXTURE_2D, GL11.GL_TEXTURE_WRAP_S, GL11.GL_CLAMP);
        GL11.glTexParameteri(GL11.GL_TEXTURE_2D, GL11.GL_TEXTURE_WRAP_T, GL11.GL_CLAMP);
        GL11.glTexImage2D(GL11.GL_TEXTURE_2D, 0, GL11.GL_ALPHA, loadedAtlasWidth,
                loadedAtlasHeight, 0, GL11.GL_ALPHA, GL11.GL_UNSIGNED_BYTE, buffer);
        GL11.glPopAttrib();

        cell = loadedCell;
        columns = loadedColumns;
        padding = loadedPadding;
        fontTop = loadedFontTop;
        fontHeight = loadedFontHeight;
        baseline = loadedBaseline;
        atlasScale = loadedScale;
        canonicalAscent = loadedAscent;
        atlasWidth = loadedAtlasWidth;
        atlasHeight = loadedAtlasHeight;
        codes = loadedCodes;
        widths = loadedWidths;
    }

    private static int indexOf(char c) {
        int low = 0;
        int high = codes.length - 1;
        while (low <= high) {
            int middle = (low + high) >>> 1;
            int value = codes[middle];
            if (value == c) {
                return middle;
            }
            if (value < c) {
                low = middle + 1;
            } else {
                high = middle - 1;
            }
        }
        return -1;
    }
}
